import type DimensionFeatureLayer from "../../layers/DimensionFeatureLayer.js";
import type FeatureLikeLayerView from "./FeatureLikeLayerView.js";

/**
 * Represents the [LayerView](https://developers.arcgis.com/javascript/latest/references/core/views/layers/LayerView/) of a [DimensionFeatureLayer](https://developers.arcgis.com/javascript/latest/references/core/layers/DimensionFeatureLayer/)
 * after it has been added to a [Map](https://developers.arcgis.com/javascript/latest/references/core/Map/) in either a [MapView](https://developers.arcgis.com/javascript/latest/references/core/views/MapView/) or
 * [SceneView](https://developers.arcgis.com/javascript/latest/references/core/views/SceneView/).
 *
 * The DimensionFeatureLayerView is responsible for rendering a [DimensionFeatureLayer's](https://developers.arcgis.com/javascript/latest/references/core/layers/DimensionFeatureLayer/)
 * features as [graphics](https://developers.arcgis.com/javascript/latest/references/core/Graphic/) in the [View](https://developers.arcgis.com/javascript/latest/references/core/views/View/).
 *
 * @since 5.1
 * @beta
 * @see [DimensionFeatureLayer (beta)](https://developers.arcgis.com/javascript/latest/references/core/layers/DimensionFeatureLayer/)
 */
export default abstract class DimensionFeatureLayerView extends FeatureLikeLayerView {
  /** The layer being viewed. */
  get layer(): DimensionFeatureLayer;
}